import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { cpSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

// Part 18 is generated by scripts/system-design (see its README). The JSON is what the site ships, so it has to be what
// those Python files build: a hand edit of the JSON would be overwritten by the next build, and an edit of the sources that
// was not followed by a build would never reach the site. `build.py --check` writes nothing and exits 1 on a difference.
const root = fileURLToPath(new URL("..", import.meta.url));
const build = join(root, "scripts/system-design/build.py");
const env = { ...process.env, PYTHONDONTWRITEBYTECODE: "1" };

const python = spawnSync("python3", ["-c", "import sys; sys.exit(0 if sys.version_info >= (3, 10) else 1)"], { env });
const skip = python.status === 0 ? false : "needs python3 3.10 or newer on PATH";

function check(repo: string) {
  const r = spawnSync("python3", [build, "--check", repo], { env, encoding: "utf8", timeout: 60_000 });
  return { status: r.status, output: `${r.stdout}${r.stderr}` };
}

test("system-design.json and the Part's interview entry are what scripts/system-design builds", { skip }, () => {
  const r = check(root);
  assert.equal(r.status, 0, r.output);
  assert.match(r.output, /40 sections, 182 sources: the two files are up to date/);
});

test("the check notices a hand edit of system-design.json, and leaves the files alone", { skip }, () => {
  const dir = mkdtempSync(join(tmpdir(), "system-design-check-"));
  try {
    mkdirSync(join(dir, "src/lib"), { recursive: true });
    mkdirSync(join(dir, "src/content"), { recursive: true });
    cpSync(join(root, "src/lib/content-schema.ts"), join(dir, "src/lib/content-schema.ts"));
    cpSync(join(root, "src/content/interview.json"), join(dir, "src/content/interview.json"));
    const edited = readFileSync(join(root, "src/content/system-design.json"), "utf8").replace("How a Request Travels", "how a request travels");
    writeFileSync(join(dir, "src/content/system-design.json"), edited);

    const r = check(dir);
    assert.equal(r.status, 1, r.output);
    assert.match(r.output, /DIFFERS src\/content\/system-design\.json/);
    assert.doesNotMatch(r.output, /DIFFERS src\/content\/interview\.json/);
    assert.equal(readFileSync(join(dir, "src/content/system-design.json"), "utf8"), edited, "--check must not write");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});
